+ * Sanitize an SVG element by removing potentially dangerous elements and attributes.
+ * @param {SVGElement} svg - The SVG element to sanitize.
+ */
+const sanitizeSvg = function (svg) {
+    // Remove script elements
+    const scripts = svg.querySelectorAll('script');
+    for (let i = 0; i < scripts.length; i++) {
+        scripts[i].parentNode.removeChild(scripts[i]);
+    }
+
+    // Remove event handler attributes and javascript: URLs from all elements
+    const allElements = svg.querySelectorAll('*');
+    for (let i = 0; i < allElements.length; i++) {
+        const element = allElements[i];
+        const attributes = Array.prototype.slice.call(element.attributes);
+        for (let j = 0; j < attributes.length; j++) {
+            const attr = attributes[j];
+            const attrName = attr.name.toLowerCase();
+            // Remove on* event handlers (onclick, onload, onerror, etc.)
+            if (attrName.startsWith('on')) {
+                element.removeAttribute(attr.name);
+            }
+            // Remove javascript: URLs in href attributes
+            if ((attrName === 'href' || attrName === 'xlink:href') &&
+                attr.value.trim().toLowerCase().startsWith('javascript:')) {
+                element.removeAttribute(attr.name);
+            }
+        }
+    }
+};
